        api({ host: '', uri: '/accounts/consent/', authentication: user.token,
            withCredentials: true, method: 'POST', useCsrf: true,
            json: {action: ACTION_TYPES.REQUEST_PARENTAL_CONSENT, parent_email: email}
        }, (err, body, res) => {
            setLoading(false);
            if (!err && res.statusCode === 200) setConsentRequested(true);
        });
    }, [user]);

